const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0111/g, 'd')
    .replace(/\u0110/g, 'D');
}
const raw = String(source.rawText || source.text || source.query || args.query || message.text || payload.text || '').trim();
const text = normalize(source.text || source.query || args.query || raw);
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const calendarId = source.calendarId || args.calendarId || payload.calendarId || 'kuminhuynhdoan@gmail.com';
function pad(n) { return String(n).padStart(2, '0'); }
function iso(d, h = 0, m = 0, end = false) {
  return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(h)}:${pad(m)}:${end ? '59' : '00'}+07:00`;
}
function startOfDay(d) { const x = new Date(d); x.setHours(0,0,0,0); return x; }
function endOfDay(d) { const x = new Date(d); x.setHours(23,59,59,0); return x; }
function nextWeekday(base, targetDow, nextWeek = false) {
  const d = startOfDay(base);
  let diff = (targetDow - d.getDay() + 7) % 7;
  if (diff === 0) diff = 7;
  if (nextWeek) diff += 7;
  d.setDate(d.getDate() + diff);
  return d;
}
const now = new Date();
const explicitDateFrom = String(source.dateFrom || args.dateFrom || '').trim();
const explicitDateTo = String(source.dateTo || args.dateTo || '').trim();
let afterDate = explicitDateFrom ? new Date(explicitDateFrom) : now;
let beforeDate = explicitDateTo ? new Date(explicitDateTo) : new Date(now.getTime() + 1000 * 60 * 60 * 24 * 30);
if (explicitDateFrom || explicitDateTo) {
  // structured date filters already provided
} else if (/cuoi tuan nay/.test(text)) {
  afterDate = nextWeekday(now, 6, false);
  beforeDate = endOfDay(new Date(afterDate.getTime() + 86400000));
} else if (/cuoi tuan sau/.test(text)) {
  afterDate = nextWeekday(now, 6, true);
  beforeDate = endOfDay(new Date(afterDate.getTime() + 86400000));
} else if (/tuan sau/.test(text)) {
  const monday = nextWeekday(now, 1, true);
  afterDate = monday;
  beforeDate = endOfDay(new Date(monday.getTime() + 6 * 86400000));
} else if (/ngay mai|mai/.test(text)) {
  afterDate = startOfDay(new Date(now.getTime() + 86400000));
  beforeDate = endOfDay(afterDate);
} else {
  const weekdayMatch = text.match(/thu\s*(2|3|4|5|6|7)|chu nhat/);
  if (weekdayMatch) {
    let targetDow = weekdayMatch[1] ? Number(weekdayMatch[1]) - 1 : 0;
    const nextWeek = /tuan sau/.test(text);
    afterDate = nextWeekday(now, targetDow, nextWeek);
    beforeDate = endOfDay(afterDate);
  }
}
const explicitQuery = String(source.query || args.query || '').trim();
const query = (explicitQuery || raw)
  .replace(/^(tim lich|tim su kien|search event|find event|xem lich voi|lich)\s*/i, '')
  .replace(/\b(hom nay|ngay mai|mai|tuan sau|tuan nay|cuoi tuan nay|cuoi tuan sau|thu\s*[2-7]|chu nhat)\b/gi, '')
  .replace(/\s+/g, ' ')
  .trim();
return [{ json: { ...source, payload, message, rawText: raw, text, chatId, calendarId, query, limit: Number(source.limit || args.limit || 5) || 5, after: explicitDateFrom || iso(afterDate), before: explicitDateTo || iso(beforeDate, 23, 59, true) } }];

function toDate(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

function formatDate(date) {
  return new Intl.DateTimeFormat('vi-VN', {
    timeZone: 'Asia/Ho_Chi_Minh',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  }).format(date);
}

function formatTime(date) {
  return new Intl.DateTimeFormat('vi-VN', {
    timeZone: 'Asia/Ho_Chi_Minh',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }).format(date);
}

function formatRange(startValue, endValue) {
  const startDate = toDate(startValue);
  const endDate = toDate(endValue);
  if (!startDate) return startValue || '';
  if (!endDate) return `${formatTime(startDate)}, ${formatDate(startDate)}`;
  const sameDay = startDate.toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' }) === endDate.toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' });
  if (sameDay) return `${formatTime(startDate)} - ${formatTime(endDate)}, ${formatDate(startDate)}`;
  return `${formatTime(startDate)}, ${formatDate(startDate)} đến ${formatTime(endDate)}, ${formatDate(endDate)}`;
}

const source = $('Chuan Bi Tim Lich').item.json || {};
const rows = $input.all()
  .map((item) => item.json || {})
  .filter((event) => event && Object.keys(event).length > 0 && (event.id || event.summary || event.start || event.end))
  .slice(0, 3);
const query = source.query || source.rawText || '';
const links = [];

let text = '';
if (!rows.length) {
  text = query
    ? `Mia chưa tìm thấy lịch nào khớp với "${query}".`
    : 'Mia chưa tìm thấy lịch phù hợp.';
} else {
  text = query
    ? `Mia tìm thấy ${rows.length} lịch khá khớp với "${query}":`
    : `Mia tìm thấy ${rows.length} lịch phù hợp:`;
  rows.forEach((event, index) => {
    const title = event.summary || 'Không có tiêu đề';
    const start = event.start?.dateTime || event.start?.date || '';
    const end = event.end?.dateTime || event.end?.date || '';
    text += `\n${index + 1}. ${title} — ${formatRange(start, end)}`;
    if (event.htmlLink && !links.includes(event.htmlLink)) links.push(event.htmlLink);
  });
  if (links.length) {
    text += '\n\nMở nhanh lịch:';
    links.slice(0, 3).forEach((link, index) => {
      text += `\n${index + 1}. ${link}`;
    });
  }
}

return [{
  json: {
    ok: true,
    tool: 'calendar.find_event',
    chatId: source.chatId || '',
    text: text.trim(),
    links: links.slice(0, 3),
    result: { events: rows },
    meta: { query, count: rows.length }
  }
}];
